fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut i: i32 = 0;
        while i < 4 {
            host::display::state_set(1 + i, i + 1);
            host::display::state_set(5 + i, w + 40 + i * 130);
            i = i + 1;
        }
        host::display::state_set(9, t);
        host::display::state_set(11, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(12) == 0;
    host::display::state_set(12, down);
    let sec: i32 = (t - host::display::state_get(9)) / 60;
    if host::display::state_get(11) == 1 {
        host::display::clear(0x0a0a14);
        host::display::draw_string(130, 180, "SHIP LOST", 0xff4040, 4);
        host::display::draw_string(120, 250, "SURVIVED", 0x808080, 2);
        host::display::draw_number(290, 244, host::display::state_get(13), 0xffffff, 3);
        host::display::draw_string(120, 284, "BEST", 0x808080, 2);
        host::display::draw_number(290, 278, host::display::state_get(10), 0x00ff88, 3);
        host::display::draw_string(120, 350, "TAP TO LAUNCH", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let mut px: i32 = host::display::pointer_x();
        let mut py: i32 = host::display::pointer_y();
        if px < 10 { px = 10; }
        if px > w - 30 { px = w - 30; }
        if py < 10 { py = 10; }
        if py > h - 30 { py = h - 30; }
        host::display::clear(0x0a0a14);
        let mut s: i32 = 0;
        while s < 20 {
            let sy: i32 = hash(s * 7 + 1) % h;
            let sx: i32 = (hash(s * 3 + 2) % w - (t * (1 + s % 3)) % w + w) % w;
            host::display::fill_rect(sx, sy, 2, 2, 0x303048);
            s = s + 1;
        }
        let mut i2: i32 = 0;
        while i2 < 4 {
            let rnd: i32 = host::display::state_get(1 + i2);
            let ay: i32 = 20 + hash(rnd * 31 + i2) % (h - 80);
            let asz: i32 = 20 + hash(rnd * 11 + i2) % 20;
            let spd: i32 = 3 + hash(rnd * 5 + i2) % 4;
            let mut ax: i32 = host::display::state_get(5 + i2) - spd;
            if ax < -50 {
                host::display::state_set(1 + i2, rnd + 4);
                ax = w + 20 + hash(rnd * 17 + i2) % 120;
            }
            host::display::state_set(5 + i2, ax);
            if px + 20 > ax && px < ax + asz && py + 20 > ay && py < ay + asz {
                host::display::state_set(11, 1);
                host::display::state_set(13, sec);
                if sec > host::display::state_get(10) {
                    host::display::state_set(10, sec);
                }
            }
            host::display::fill_rect(ax, ay, asz, asz, 0x707078);
            host::display::fill_rect(ax + asz / 4, ay + asz / 4, asz / 4, asz / 4, 0x50505a);
            i2 = i2 + 1;
        }
        host::display::fill_triangle(px, py + 10, px + 20, py, px + 20, py + 20, 0xffffff);
        host::display::fill_rect(px + 20, py + 6, 6, 8, 0xff6600);
        host::display::draw_number(w - 90, 12, sec, 0xffffff, 3);
    }
    host::display::present();
}
